export interface AutogenState {
    /** the knobs, plus `allow`: the catalog ids Grow may use */
    params: Record<string, number | boolean | string[]>;
    /** generated ids the human deleted — regeneration must not bring them back */
    deleted: string[];
    ran?: string;
