    version: 1;
    items: StructureItem[];
}
export declare const STRUCTURE_KINDS: {
    kind: StructureKind;
    label: string;
    note: string;
}[];
export declare const NEUTRAL: Adjust;
/** The texture sets tools/surfaces/gen.py bakes; `null` means "whatever the classifier said". */
export declare const SURFACE_CLASSES: string[];
/** What trees.ts can actually grow; `null` means "pick by height as usual". */
export declare const SPECIES: string[];
