/**
 * Areas written before a key existed do not have it, and `undefined` is not `NEUTRAL[key]`: the
 * crop-row default is "set it from the road when it is still 0", and an absent key is never 0, so
 * it silently never fired and the two row fields never reached the file. Fill every area's
 * `adjust` from NEUTRAL on the way in and the rest of the editor can assume a complete object.
 * The viewer reads `adjust` as a Partial and does not care either way.
 */
export declare function loadAdjustments(slug: string): Promise<Adjustments>;
export declare const saveAdjustments: (slug: string, doc: Adjustments) => Promise<number>;
export declare const loadPlacements: (slug: string) => Promise<Placements>;
export declare const savePlacements: (slug: string, doc: Placements) => Promise<number>;
export declare const loadStructures: (slug: string) => Promise<Structures>;
export declare const saveStructures: (slug: string, doc: Structures) => Promise<number>;
/** Lowest free `a-NN` / `p-NN` / `st-NN`, so hand-drawn ids never collide with the generated ones. */
export declare function nextId(prefix: string, taken: Iterable<string>): string;
/** Even-odd point-in-polygon in the site frame; picking an area under the cursor. */
export declare function inside(poly: [number, number][], x: number, y: number): boolean;
/** Shoelace area, m² — the panel shows it so a stray click is obvious. */
export declare function areaOf(poly: [number, number][]): number;

